use convert_case::{delim_boundary, split};
fn main() {
    std::panic::set_hook(Box::new(|_| {}));
    assert_eq!(split(&"a::b", &[delim_boundary!("::")]), vec!["a", "b"]);
    let panic = std::panic::catch_unwind(|| split(&"a:::b", &[delim_boundary!("::")]));
    println!("overlapping custom delimiter panics: {}", panic.is_err());
    assert!(panic.is_err());
}
